export default function Map() {
  const mapRef = useRef<mapboxgl.Map | null>(null);
  const mapContainerRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    if (!mapContainerRef.current || mapRef.current) return;

    const map = new mapboxgl.Map({
      accessToken: process.env.NEXT_PUBLIC_MAPBOX_TOKEN,
      container: mapContainerRef.current,

      center: [125.613728, 7.091779],
      zoom: 12,

      style: "mapbox://styles/mapbox/standard-satellite",

      config: {
        basemap: {
          lightPreset: "day",
          colorMotorways: "#2e89ff",
        },
      },

      attributionControl: false,
      scrollZoom: false,
    });

    mapRef.current = map;

    map.addControl(
      new mapboxgl.NavigationControl(),
      "bottom-right"
    );

    map.on("load", () => {
      vehicles.forEach((vehicle) => {
        /*
         * =========================
         * ROUTE
         * =========================
         */

        const sourceId = `route-${vehicle.id}`;
        const layerId = `route-${vehicle.id}`;

        map.addSource(sourceId, {
          type: "geojson",
          data: {
            type: "Feature",
            properties: {},
            geometry: {
              type: "LineString",
              coordinates: vehicle.route,
            },
          },
        });

        map.addLayer({
          id: layerId,
          type: "line",
          source: sourceId,

          paint: {
            "line-color": "#2e89ff",
            "line-width": 3,
            "line-opacity": 0,
          },
        });

        /*
         * =========================
         * VEHICLE MARKER
         * =========================
         */

        const markerElement = document.createElement("div");

        markerElement.className =
          "h-4 w-4 cursor-pointer rounded-full border-2 border-white bg-blue-500 shadow-lg shadow-blue-500/50";

        /*
         * =========================
         * POPUP
         * =========================
         */

        const popup = new mapboxgl.Popup({
          offset: 14,
          closeButton: false,
          closeOnClick: false,
        }).setHTML(`
          <div style="
            min-width: 180px;
            padding: 4px;
            font-family: sans-serif;
          ">
            <div style="
              font-size: 11px;
              font-weight: 600;
              color: #64748b;
              text-transform: uppercase;
              letter-spacing: 0.08em;
            ">
              ${vehicle.id}
            </div>

            <div style="
              margin-top: 6px;
              font-size: 14px;
              font-weight: 600;
              color: #0f172a;
            ">
              → ${vehicle.destination}
            </div>

            <div style="
              margin-top: 6px;
              font-size: 12px;
              color: #64748b;
            ">
              ETA ${vehicle.eta} · ${vehicle.status}
            </div>
          </div>
        `);

        const marker = new mapboxgl.Marker(markerElement)
          .setLngLat(vehicle.location)
          .addTo(map);

        /*
         * =========================
         * HOVER
         * =========================
         */

        markerElement.addEventListener("mouseenter", () => {
          popup
            .setLngLat(vehicle.location)
            .addTo(map);

          // Highlight route
          map.setPaintProperty(
            layerId,
            "line-width",
            5
          );

          map.setPaintProperty(
            layerId,
            "line-opacity",
            1
          );
        });

        markerElement.addEventListener("mouseleave", () => {
          popup.remove();

          // Return route to normal
          map.setPaintProperty(
            layerId,
            "line-width",
            0
          );

          map.setPaintProperty(
            layerId,
            "line-opacity",
            0
          );
        });
      });
    });

    return () => {
      map.remove();
      mapRef.current = null;
    };
  }, []);

  return (
    <div
      ref={mapContainerRef}
      className="h-full w-full"
    />
  );
}